// ===== 選擇題題庫：TOEIC（來自 toeic_reading_practice-v3.json）=====
// 欄位說明同 mcq-junior.js；詳解含「題目中文翻譯」「答案選項中文說明」「文法解析」。
MCQ_SETS.push({
  id: "toeic",
  name: "TOEIC",
  filters: ["分類"],
  questions: [
    {"id": "toetic_20261026_read_ans_101", "f": {"分類": "詞性"}, "ref": "toetic_20261026_read_ans 第101題", "q": "Judging from recent sales, Athena Footwear's marketing campaign has _______ been a success.", "o": ["(A) clear", "(B) clearly", "(C) clearer", "(D) clearing"], "a": "B", "e": "【題目中文翻譯】\n從最近的銷售數字來看，雅典娜鞋業的行銷活動顯然獲得了成功。\n\n【答案選項中文說明與詞性】\n(A) clear (形容詞/動詞) (B) clearly (副詞) (C) clearer (比較級) (D) clearing (動名詞/分詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) clearly\n解析說明：空格位於助動詞 has 與連繫動詞 been 之間，修飾動詞片語或全句，應填入副詞 clearly。選項為同字根不同詞性，分類為「詞性」。"},
    {"id": "toetic_20261026_read_ans_102", "f": {"分類": "詞性"}, "ref": "toetic_20261026_read_ans 第102題", "q": "The _______ of a new chief executive officer at Perillon Industrial will be announced before the shareholder meeting.", "o": ["(A) appoints", "(B) appoint", "(C) appointment", "(D) appointed"], "a": "C", "e": "【題目中文翻譯】\n佩里隆工業新任執行長的任命將在股東大會前宣布。\n\n【答案選項中文說明與詞性】\n(A) appoints (動詞三單) (B) appoint (動詞原形) (C) appointment (名詞) (D) appointed (過去式/分詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) appointment\n解析說明：定冠詞 The 後面接名詞作主詞，故事選名詞 appointment。選項為同字根衍生詞，分類為「詞性」。"},
    {"id": "toetic_20261026_read_ans_103", "f": {"分類": "詞性"}, "ref": "toetic_20261026_read_ans 第103題", "q": "Many Grayton Construction employees know how to use a forklift, but only a few of _______ are licensed to operate them.", "o": ["(A) they", "(B) them", "(C) theirs", "(D) themselves"], "a": "B", "e": "【題目中文翻譯】\n格雷頓建設的許多員工都知道如何使用堆高機，但只有少數人獲得操作執照。\n\n【答案選項中文說明與詞性】\n(A) they (主格代名詞) (B) them (受格代名詞) (C) theirs (所有格代名詞) (D) themselves (反身代名詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) them\n解析說明：介系詞 of 後面接受格代名詞，作介系詞的受詞，故選 them。選項屬於代名詞格位變化，分類為「詞性」。"},
    {"id": "toetic_20261026_read_ans_104", "f": {"分類": "字彙"}, "ref": "toetic_20261026_read_ans 第104題", "q": "At Kaplan Optics, trainees are _______ to learn from each other by sharing their experiences from past design projects.", "o": ["(A) responded", "(B) excelled", "(C) maintained", "(D) encouraged"], "a": "D", "e": "【題目中文翻譯】\n在卡普蘭光學，實習生被鼓勵透過分享過去設計專案的經驗互相學習。\n\n【答案選項中文說明與詞性】\n(A) responded (回應) (B) excelled (擅長) (C) maintained (維護) (D) encouraged (鼓勵)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) encouraged\n解析說明：語意為「被鼓勵 (are encouraged to) 互相學習」，4個選項皆為不同意義的動詞單字，故分類為「字彙」。"},
    {"id": "toetic_20261026_read_ans_105", "f": {"分類": "介系詞"}, "ref": "toetic_20261026_read_ans 第105題", "q": "_______ his medical record, Mr. Richmond was admitted to Maryport General Hospital on November 22.", "o": ["(A) As soon as", "(B) In compliance with", "(C) According to", "(D) Instead of"], "a": "C", "e": "【題目中文翻譯】\n根據他的病歷，里士滿先生於 11 月 22 日入住瑪麗港總醫院。\n\n【答案選項中文說明與詞性】\n(A) As soon as (一...就, 連接詞) (B) In compliance with (符合, 介系詞片語) (C) According to (根據, 介系詞片語) (D) Instead of (代替, 介系詞片語)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(C) According to\n解析說明：後接名詞 his medical record，表達「根據病歷紀錄」，故選介系詞片語 According to。選項多為介系詞/介系詞片語，分類為「介系詞」。"},
    {"id": "toetic_20261026_read_ans_106", "f": {"分類": "連結詞"}, "ref": "toetic_20261026_read_ans 第106題", "q": "Trentex Consulting security guards must do _______ they can to ensure the safety of employees and visitors.", "o": ["(A) whatever", "(B) whenever", "(C) however", "(D) wherever"], "a": "A", "e": "【題目中文翻譯】\n特倫特克斯諮詢公司的安衛警衛必須盡其所能，確保員工和訪客的安全。\n\n【答案選項中文說明與詞性】\n(A) whatever (無論什麼/任何事) (B) whenever (無論何時) (C) however (無論如何) (D) wherever (無論何地)\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(A) whatever\n解析說明：作動詞 do 的受詞，whatever they can 表示「任何他們能做的事」。選項皆為複合關係代名詞/副詞（連接詞類），分類為「連結詞」。"},
    {"id": "toetic_20261026_read_ans_107", "f": {"分類": "字彙"}, "ref": "toetic_20261026_read_ans 第107題", "q": "Lewis Palmer has been assigned to _______ the cause of a recent equipment malfunction at the plant.", "o": ["(A) inform", "(B) determine", "(C) prevent", "(D) conclude"], "a": "B", "e": "【題目中文翻譯】\n路易斯·帕爾默已被指派去查明該廠近期設備故障的原因。\n\n【答案選項中文說明與詞性】\n(A) inform (通知) (B) determine (查明/決定) (C) prevent (預防) (D) conclude (下結論)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) determine\n解析說明：配合受詞 the cause (原因)，表達「查明/確定原因」，故選 determine。選項為4個不同動詞，分類為「字彙」。"},
    {"id": "toetic_20261026_read_ans_108", "f": {"分類": "詞性"}, "ref": "toetic_20261026_read_ans 第108題", "q": "The relationships that the staff members have formed with clients have _______ contributed to the company's success.", "o": ["(A) signified", "(B) significant", "(C) significantly", "(D) significance"], "a": "C", "e": "【題目中文翻譯】\n員工與客戶建立的關係對公司的成功有著顯著的貢獻。\n\n【答案選項中文說明與詞性】\n(A) signified (動詞過去式) (B) significant (形容詞) (C) significantly (副詞) (D) significance (名詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) significantly\n解析說明：空格修飾動詞 contributed，應填入副詞 significantly。選項為同字根之詞性變化，分類為「詞性」。"},
    {"id": "toetic_20261026_read_ans_109", "f": {"分類": "詞性"}, "ref": "toetic_20261026_read_ans 第109題", "q": "_______ at the new McLaren Institute is primarily centered on solar power generation.", "o": ["(A) Research", "(B) Researchers", "(C) Researched", "(D) Researches"], "a": "A", "e": "【題目中文翻譯】\n新邁克拉倫研究所的研究主要集中在太陽能發電上。\n\n【答案選項中文說明與詞性】\n(A) Research (不可數名詞/研究) (B) Researchers (可數名詞複數/研究員) (C) Researched (動詞過去式) (D) Researches (動詞三單/名詞複數)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) Research\n解析說明：動詞為單數 is，且主詞指「研究（不可數名詞）」，故選 Research。選項為同字根詞性及單複數變化，分類為「詞性」。"},
    {"id": "toetic_20261026_read_ans_110", "f": {"分類": "字彙"}, "ref": "toetic_20261026_read_ans 第110題", "q": "Wentworth Contractors has adopted the _______ latest techniques for mixing cement.", "o": ["(A) so", "(B) many", "(C) much", "(D) very"], "a": "D", "e": "【題目中文翻譯】\n溫特沃斯承包商採用了最新穎的水泥混合技術。\n\n【答案選項中文說明與詞性】\n(A) so (如此) (B) many (許多) (C) much (非常) (D) very (正是/最)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) very\n解析說明：the very + 最高級 (the very latest) 用於加強最高級語意，表示「最新的」。選項為不同副詞/限定詞，分類為「字彙」。"},
    {"id": "toetic_20261026_read_ans_111", "f": {"分類": "介系詞"}, "ref": "toetic_20261026_read_ans 第111題", "q": "Everyone _______ the parking attendants on duty will gather to hear the president's announcement.", "o": ["(A) rather", "(B) except", "(C) other", "(D) between"], "a": "B", "e": "【題目中文翻譯】\n除了值班的停車場管理員外，所有人都要集合聽取總裁的宣布。\n\n【答案選項中文說明與詞性】\n(A) rather (寧願) (B) except (除了...之外) (C) other (其他的) (D) between (在...之間)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(B) except\n解析說明：Everyone except... 表示「除了...以外的每個人」。except 在此作介系詞使用，分類為「介系詞」。"},
    {"id": "toetic_20261026_read_ans_112", "f": {"分類": "連結詞"}, "ref": "toetic_20261026_read_ans 第112題", "q": "Topaz Tennis Club members who want to renew their membership card _______ it expires may do so at the reception counter.", "o": ["(A) still", "(B) until", "(C) before", "(D) whether"], "a": "C", "e": "【題目中文翻譯】\n黃玉網球俱樂部會員若想在會員卡到期前續卡，可至接待櫃檯辦理。\n\n【答案選項中文說明與詞性】\n(A) still (仍然) (B) until (直到) (C) before (在...之前) (D) whether (是否)\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(C) before\n解析說明：引導時間副詞子句 it expires，語意為「在到期之前」，故選屬連接詞性質的 before。選項包含連接詞/副詞，分類為「連結詞」。"},
    {"id": "toetic_20261026_read_ans_113", "f": {"分類": "詞性"}, "ref": "toetic_20261026_read_ans 第113題", "q": "The seminar room's _______ seating capacity is only forty, so Professor Ramos delivered his presentation in the auditorium.", "o": ["(A) maximum", "(B) maximization", "(C) maximizing", "(D) maximize"], "a": "A", "e": "【題目中文翻譯】\n研討室的最大座位容量只有四十人，因此拉莫斯教授在大禮堂發表了他的簡報。\n\n【答案選項中文說明與詞性】\n(A) maximum (形容詞/最大值的) (B) maximization (名詞/最大化) (C) maximizing (分詞) (D) maximize (動詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) maximum\n解析說明：修飾名詞片語 seating capacity，需填入形容詞 maximum。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "toetic_20261026_read_ans_114", "f": {"分類": "連結詞"}, "ref": "toetic_20261026_read_ans 第114題", "q": "Applications for admission can be processed _______ all the necessary documents have been received.", "o": ["(A) first", "(B) soon", "(C) next", "(D) once"], "a": "D", "e": "【題目中文翻譯】\n一旦收到所有必要文件，即可開始處理入學申請。\n\n【答案選項中文說明與詞性】\n(A) first (首先) (B) soon (很快地) (C) next (接下來) (D) once (一旦, 連接詞)\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(D) once\n解析說明：連接兩個完整的句子（子句），表達「一旦...就...」，應選擇從屬連接詞 once。選項涉及連接詞功能，分類為「連結詞」。"},
    {"id": "toetic_20261026_read_ans_115", "f": {"分類": "詞性"}, "ref": "toetic_20261026_read_ans 第115題", "q": "A replacement will not be hired until January unless the division _______ needs to fill the position immediately.", "o": ["(A) true", "(B) truth", "(C) truly", "(D) truthful"], "a": "C", "e": "【題目中文翻譯】\n除非該部門確實需要立即填補該職缺，否則要到一月才會聘用替代人員。\n\n【答案選項中文說明與詞性】\n(A) true (形容詞) (B) truth (名詞) (C) truly (副詞) (D) truthful (形容詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) truly\n解析說明：空格修飾動詞 needs，應填入副詞 truly（確實地）。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "toetic_20261026_read_ans_116", "f": {"分類": "字彙"}, "ref": "toetic_20261026_read_ans 第116題", "q": "The number of subscribers to the community newsletter reached 12,500 this week following a steady _______ in subscriptions in March.", "o": ["(A) extension", "(B) addition", "(C) increase", "(D) raise"], "a": "C", "e": "【題目中文翻譯】\n在三月份訂閱量穩定增加之後，本週社區通訊的訂閱人數達到 12,500 人。\n\n【答案選項中文說明與詞性】\n(A) extension (延伸) (B) addition (附加) (C) increase (增加) (D) raise (加薪/提升)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) increase\n解析說明：a steady increase in... 表示「...的穩定成長/增加」。4個選項為不同名詞單字，分類為「字彙」。"},
    {"id": "toetic_20261026_read_ans_117", "f": {"分類": "詞性"}, "ref": "toetic_20261026_read_ans 第117題", "q": "Mr. Granger will send applications to two different agencies to obtain the permits _______ for erecting a barn.", "o": ["(A) required", "(B) requiring", "(C) requires", "(D) requirement"], "a": "A", "e": "【題目中文翻譯】\n格蘭傑先生將向兩個不同機構提出申請，以取得建造穀倉所需的許可證。\n\n【答案選項中文說明與詞性】\n(A) required (過去分詞/被要求的) (B) requiring (現在分詞) (C) requires (動詞三單) (D) requirement (名詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) required\n解析說明：修飾前面的名詞 permits，表達「被需要的許可證」，用過去分詞 required 後置修飾。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "toetic_20261026_read_ans_118", "f": {"分類": "連結詞"}, "ref": "toetic_20261026_read_ans 第118題", "q": "Donna Clark asked her assistant to find out which galleries exhibit the works _______ are shown in the book of paintings.", "o": ["(A) such", "(B) that", "(C) about", "(D) what"], "a": "B", "e": "【題目中文翻譯】\n唐娜·克拉克請助理去查明哪些畫廊展出了該畫冊中展示的作品。\n\n【答案選項中文說明與詞性】\n(A) such (如此) (B) that (關係代名詞) (C) about (關於) (D) what (複合關代)\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(B) that\n解析說明：引導關係子句修飾先行詞 the works，作子句的主詞，故選關係代名詞 that。分類為「連結詞」。"},
    {"id": "toetic_20261026_read_ans_119", "f": {"分類": "詞性"}, "ref": "toetic_20261026_read_ans 第119題", "q": "The Sanderton Public Library will be closed for renovations _______ on Monday, May 4.", "o": ["(A) will begin", "(B) has begun", "(C) beginner", "(D) beginning"], "a": "D", "e": "【題目中文翻譯】\n桑德頓市立圖書館將從 5 月 4 日星期一開始閉館進行裝修。\n\n【答案選項中文說明與詞性】\n(A) will begin (動詞未來式) (B) has begun (完成式) (C) beginner (名詞) (D) beginning (分詞/介系詞化)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) beginning\n解析說明：beginning on + 日期 表示「自...起/從...開始」。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "toetic_20261026_read_ans_120", "f": {"分類": "介系詞"}, "ref": "toetic_20261026_read_ans 第120題", "q": "This e_mail serves _______ confirmation that Glennfirth Hotel has received your reservation request.", "o": ["(A) with", "(B) to", "(C) as", "(D) for"], "a": "C", "e": "【題目中文翻譯】\n此電子郵件作為格倫弗斯飯店已收到您的預訂請求的確認函。\n\n【答案選項中文說明與詞性】\n(A) with (帶有) (B) to (到) (C) as (作為) (D) for (為了)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(C) as\n解析說明：serve as... 為固定搭配，表示「充當/作為...」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "toetic_20261026_read_ans_121", "f": {"分類": "詞性"}, "ref": "toetic_20261026_read_ans 第121題", "q": "Mr. Irwin agreed to write letters of _______ for the interns who had successfully completed all the requirements of their internships.", "o": ["(A) recommends", "(B) recommended", "(C) recommending", "(D) recommendation"], "a": "D", "e": "【題目中文翻譯】\n歐文先生同意為成功完成實習所有要求的實習生撰寫推薦信。\n\n【答案選項中文說明與詞性】\n(A) recommends (動詞三單) (B) recommended (過去式) (C) recommending (分詞) (D) recommendation (名詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) recommendation\n解析說明：letters of recommendation 為固定片語（推薦信），介系詞 of 後接名詞 recommendation。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "toetic_20261026_read_ans_122", "f": {"分類": "字彙"}, "ref": "toetic_20261026_read_ans 第122題", "q": "Instructions have been posted above each washing machine so that customers can _______ refer to them.", "o": ["(A) commonly", "(B) consecutively", "(C) eagerly", "(D) easily"], "a": "D", "e": "【題目中文翻譯】\n每台洗衣機上方都張貼了說明，以便顧客輕鬆參考。\n\n【答案選項中文說明與詞性】\n(A) commonly (通常地) (B) consecutively (連續地) (C) eagerly (熱切地) (D) easily (輕易地/輕鬆地)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) easily\n解析說明：easily refer to them 表示「輕鬆地參考說明」。4個選項為不同意義副詞單字，分類為「字彙」。"},
    {"id": "toetic_20261026_read_ans_123", "f": {"分類": "字彙"}, "ref": "toetic_20261026_read_ans 第123題", "q": "Hospital nurses are _______ to take paid vacation days after a six_month probationary period.", "o": ["(A) dependable", "(B) necessary", "(C) eligible", "(D) accurate"], "a": "C", "e": "【題目中文翻譯】\n醫院護理師在六個月試用期滿後有資格享受有薪年假。\n\n【答案選項中文說明與詞性】\n(A) dependable (可靠的) (B) necessary (必要的) (C) eligible (有資格的) (D) accurate (準確的)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) eligible\n解析說明：be eligible to V 表示「有資格做...」。4個選項為不同形容詞單字，分類為「字彙」。"},
    {"id": "toetic_20261026_read_ans_124", "f": {"分類": "字彙"}, "ref": "toetic_20261026_read_ans 第124題", "q": "Hospital nurses are required to take paid vacation days after a six_month probationary period.", "o": ["(A) dependable", "(B) necessary", "(C) eligible", "(D) required"], "a": "C", "e": "【題目中文翻譯】\n醫院護理師在過試用期後即符合帶薪休假的資格。\n\n【答案選項中文說明與詞性】\n(A) dependable (可信賴的) (B) necessary (必要的) (C) eligible (符合條件/有資格的) (D) required (被要求的)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) eligible\n解析說明：be eligible to 表示符合權利/資格條件。4個選項為不同字彙，分類為「字彙」。"},
    {"id": "toetic_20261026_read_ans_125", "f": {"分類": "字彙"}, "ref": "toetic_20261026_read_ans 第125題", "q": "After working in Australia for seven years, Lisa Marley has _______ to Toronto to take a managerial position.", "o": ["(A) considered", "(B) returned", "(C) removed", "(D) visited"], "a": "B", "e": "【題目中文翻譯】\n在澳洲工作七年後，麗莎·馬利已返回多倫多擔任管理職務。\n\n【答案選項中文說明與詞性】\n(A) considered (考慮) (B) returned (返回) (C) removed (移除) (D) visited (造訪)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) returned\n解析說明：returned to Toronto 表示「返回多倫多」。4個選項為不同動詞，分類為「字彙」。"},
    {"id": "toetic_20261026_read_ans_126", "f": {"分類": "介系詞"}, "ref": "toetic_20261026_read_ans 第126題", "q": "The turnout for yesterday's country music festival was larger than anticipated, _______ the poor weather.", "o": ["(A) even", "(B) notwithstanding", "(C) concerning", "(D) through"], "a": "B", "e": "【題目中文翻譯】\n儘管天氣不佳，昨天鄉村音樂節的出席人數仍高於預期。\n\n【答案選項中文說明與詞性】\n(A) even (甚至) (B) notwithstanding (儘管, 介系詞) (C) concerning (關於) (D) through (透過)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(B) notwithstanding\n解析說明：notwithstanding the poor weather 作介系詞使用，表示「儘管天氣惡劣」。選項屬介系詞功能，分類為「介系詞」。"},
    {"id": "toetic_20261026_read_ans_127", "f": {"分類": "字彙"}, "ref": "toetic_20261026_read_ans 第127題", "q": "The new bins have a lid that flips up for easy _______ of large bags of garbage.", "o": ["(A) allowance", "(B) rejection", "(C) disposal", "(D) dismissal"], "a": "C", "e": "【題目中文翻譯】\n新型垃圾桶設有可向上翻開的蓋子，方便處置大袋垃圾。\n\n【答案選項中文說明與詞性】\n(A) allowance (津貼) (B) rejection (拒絕) (C) disposal (處置/丟棄) (D) dismissal (解雇)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) disposal\n解析說明：disposal of garbage 為習慣用語（垃圾處理/丟棄）。4個選項為不同名詞單字，分類為「字彙」。"},
    {"id": "toetic_20261026_read_ans_128", "f": {"分類": "詞性"}, "ref": "toetic_20261026_read_ans 第128題", "q": "Although the YRL_11 monitor looks _______ to other models, it is made of a brand_new lightweight material.", "o": ["(A) similarity", "(B) similarities", "(C) similar", "(D) similarly"], "a": "C", "e": "【題目中文翻譯】\n雖然 YRL-11 螢幕看起來與其他型號相似，但它是由全新的輕量材料製成的。\n\n【答案選項中文說明與詞性】\n(A) similarity (名詞) (B) similarities (名詞複數) (C) similar (形容詞) (D) similarly (副詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) similar\n解析說明：連繫動詞 looks 後接形容詞作補語，look similar to...（看起來與...相似）。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "toetic_20261026_read_ans_129", "f": {"分類": "字彙"}, "ref": "toetic_20261026_read_ans 第129題", "q": "The decision to release the new smartphone ahead of schedule was based _______ on the marketing director's recommendation.", "o": ["(A) currently", "(B) evenly", "(C) gradually", "(D) solely"], "a": "D", "e": "【題目中文翻譯】\n提早發表新智慧型手機的決定完全是基於行銷總監的建議。\n\n【答案選項中文說明與詞性】\n(A) currently (目前) (B) evenly (均勻地) (C) gradually (漸漸地) (D) solely (單純地/完全地)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) solely\n解析說明：based solely on... 表示「完全基於/單純基於...」。4個選項為不同副詞，分類為「字彙」。"},
    {"id": "toetic_20261026_read_ans_130", "f": {"分類": "詞性"}, "ref": "toetic_20261026_read_ans 第130題", "q": "The event would not have been successful if we _______ the support of local businesses.", "o": ["(A) do not have", "(B) will not have", "(C) have not had", "(D) had not had"], "a": "D", "e": "【題目中文翻譯】\n如果沒有當地企業的支持，這項活動就不會取得成功。\n\n【答案選項中文說明與詞性】\n(A) do not have (現在式) (B) will not have (未來式) (C) have not had (現在完成式) (D) had not had (過去完成式)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) had not had\n解析說明：與過去事實相反的條件句：If + S + had p.p., S + would have p.p.。主要子句為 would not have been，條件子句應填 had not had。屬於動詞時態/態樣變化，分類為「詞性」。"},
    {"id": "toetic_20260530_ans_101", "f": {"分類": "詞性"}, "ref": "toetic_20260530_ans 第101題", "q": "Owing to its extensive housing development, Akron has become a _______ populated city in the last three decades.", "o": ["(A) densely", "(B) dense", "(C) denseness", "(D) density"], "a": "A", "e": "【題目中文翻譯】\n由於大規模的住宅開發，阿克倫在過去三十年中已成為一個人口稠密的城市。\n\n【答案選項中文說明與詞性】\n(A) densely (副詞) (B) dense (形容詞) (C) denseness (名詞) (D) density (名詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) densely\n解析說明：空格修飾形容詞（分詞）populated，需填入副詞 densely（稠密地）。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "toetic_20260530_ans_102", "f": {"分類": "詞性"}, "ref": "toetic_20260530_ans 第102題", "q": "Annette Choi has finally realized that the _______ of the new job outweigh the costs and will accept the offer.", "o": ["(A) beneficial", "(B) benefit", "(C) benefits", "(D) benefited"], "a": "C", "e": "【題目中文翻譯】\n安妮特·崔終於意識到新工作的好處大於代價，並將接受該工作機會。\n\n【答案選項中文說明與詞性】\n(A) beneficial (形容詞) (B) benefit (單數名詞) (C) benefits (複數名詞) (D) benefited (分詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) benefits\n解析說明：定冠詞 the 後接名詞，且動詞為複數動詞 outweigh，故主詞需用複數名詞 benefits。選項為同字根變化，分類為「詞性」。"},
    {"id": "toetic_20260530_ans_103", "f": {"分類": "詞性"}, "ref": "toetic_20260530_ans 第103題", "q": "Our CEO requests that we _______ the new branch location confidential until all employees have been informed.", "o": ["(A) are keeping", "(B) keep", "(C) kept", "(D) will keep"], "a": "B", "e": "【題目中文翻譯】\n我們的執行長要求在通知所有員工之前，對新分公司位置保密。\n\n【答案選項中文說明與詞性】\n(A) are keeping (進行式) (B) keep (動詞原形) (C) kept (過去式) (D) will keep (未來式)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) keep\n解析說明：要求動詞 request + that + S + (should) + V原形，故答案為 keep。屬於動詞文法時態/假設法變化，分類為「詞性」。"},
    {"id": "toetic_20260530_ans_104", "f": {"分類": "介系詞"}, "ref": "toetic_20260530_ans 第104題", "q": "The new employee orientation will be held at the company's headquarters _______ 9:00 A.M. to 11:00 A.M. on Monday, September 6.", "o": ["(A) from", "(B) between", "(C) at", "(D) on"], "a": "A", "e": "【題目中文翻譯】\n新員工培訓將於 9 月 6 日星期一上午 9:00 至 11:00 在公司總部舉行。\n\n【答案選項中文說明與詞性】\n(A) from (從) (B) between (在...之間) (C) at (在) (D) on (在...之上)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(A) from\n解析說明：from... to... 表示「從...到...」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "toetic_20260530_ans_105", "f": {"分類": "連結詞"}, "ref": "toetic_20260530_ans 第105題", "q": "All of the documents on our overseas projects are made available in _______ Korean and English.", "o": ["(A) both", "(B) either", "(C) also", "(D) too"], "a": "A", "e": "【題目中文翻譯】\n我們海外專案的所有文件均提供韓文和英文兩種版本。\n\n【答案選項中文說明與詞性】\n(A) both (兩者都) (B) either (兩者之一) (C) also (也) (D) too (也)\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(A) both\n解析說明：both A and B 為對等相關連接詞（韓文與英文兩者皆有）。分類為「連結詞」。"},
    {"id": "toetic_20260530_ans_106", "f": {"分類": "詞性"}, "ref": "toetic_20260530_ans 第106題", "q": "Those advertising agencies claim _______ new Web marketing promotion will boost profits more effectively than any other strategy.", "o": ["(A) themselves", "(B) their", "(C) them", "(D) they"], "a": "B", "e": "【題目中文翻譯】\n這些廣告公司聲稱，他們的新網路行銷推廣將比任何其他策略更有效地提升利潤。\n\n【答案選項中文說明與詞性】\n(A) themselves (反身代名詞) (B) their (所有格) (C) them (受格) (D) they (主格)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) their\n解析說明：修飾名詞片語 new Web marketing promotion，需填入所有格代名詞 their。屬代名詞格位變化，分類為「詞性」。"},
    {"id": "toetic_20260530_ans_107", "f": {"分類": "詞性"}, "ref": "toetic_20260530_ans 第107題", "q": "Ace Technologies Ltd. firmly believes that its high_tech products are the _______ of any available on the market.", "o": ["(A) finely", "(B) fine", "(C) finer", "(D) finest"], "a": "D", "e": "【題目中文翻譯】\n王牌科技股份有限公司堅信，其高科技產品是市場上所有產品中最優秀的。\n\n【答案選項中文說明與詞性】\n(A) finely (副詞) (B) fine (原級) (C) finer (比較級) (D) finest (最高級)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) finest\n解析說明：the + 最高級 + of any... 表示「所有中最好的/最優秀的」，故選 finest。屬於形容詞比較等級變化，分類為「詞性」。"},
    {"id": "toetic_20260530_ans_108", "f": {"分類": "詞性"}, "ref": "toetic_20260530_ans 第108題", "q": "_______ at 3 P.M. Thursday this year's state fair will commence at the Central Slate Fairgrounds.", "o": ["(A) Precise", "(B) Precisely", "(C) Preciseness", "(D) Precision"], "a": "B", "e": "【題目中文翻譯】\n今年州博覽會將於星期四下午 3 點整在中央斯萊特博覽會場地準時開始。\n\n【答案選項中文說明與詞性】\n(A) Precise (形容詞) (B) Precisely (副詞) (C) Preciseness (名詞) (D) Precision (名詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) Precisely\n解析說明：precisely at 3 P.M. 副詞修飾時間介系詞片語，表示「準時於...」。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "toetic_20260530_ans_109", "f": {"分類": "介系詞"}, "ref": "toetic_20260530_ans 第109題", "q": "All the managers admit that Ms. Jensen is fully qualified _______ the sales head position.", "o": ["(A) by", "(B) for", "(C) in", "(D) with"], "a": "B", "e": "【題目中文翻譯】\n所有經理都承認詹森女士完全有資格勝任銷售主管一職。\n\n【答案選項中文說明與詞性】\n(A) by (被) (B) for (為了/適合) (C) in (在...裡面) (D) with (與...一起)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(B) for\n解析說明：be qualified for + 名詞/職位 表示「有資格擔任...」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "toetic_20260530_ans_110", "f": {"分類": "字彙"}, "ref": "toetic_20260530_ans 第110題", "q": "As a courtesy to your coworkers please _______ from smoking anywhere other than in designated areas.", "o": ["(A) limit", "(B) prevent", "(C) refrain", "(D) stop"], "a": "C", "e": "【題目中文翻譯】\n為了禮貌起見，請勿在指定區域以外的任何地方吸菸。\n\n【答案選項中文說明與詞性】\n(A) limit (限制) (B) prevent (預防) (C) refrain (克制/戒除) (D) stop (停止)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) refrain\n解析說明：refrain from N/Ving 表示「忍住/克制不做...」。4個選項為不同動詞，分類為「字彙」。"},
    {"id": "toetic_20260530_ans_111", "f": {"分類": "連結詞"}, "ref": "toetic_20260530_ans 第111題", "q": "The city is planning to renovate the auditorium _______ several historic politicians made speeches.", "o": ["(A) whose", "(B) that", "(C) where", "(D) which"], "a": "C", "e": "【題目中文翻譯】\n該市正計劃翻新幾位歷史政治家曾發表演講的大禮堂。\n\n【答案選項中文說明與詞性】\n(A) whose (關係代名詞所有格) (B) that (關係代名詞) (C) where (關係副詞) (D) which (關係代名詞)\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(C) where\n解析說明：先行詞為地點 the auditorium，子句中缺乏地點副詞，應使用關係副詞 where。分類為「連結詞」。"},
    {"id": "toetic_20260530_ans_112", "f": {"分類": "字彙"}, "ref": "toetic_20260530_ans 第112題", "q": "After weeks of rumors in the press the candidate _______ announced his intention to run for governor.", "o": ["(A) formally", "(B) exactly", "(C) formerly", "(D) hopefully"], "a": "A", "e": "【題目中文翻譯】\n經過媒體數週的傳聞後，該候選人正式宣布參選州長。\n\n【答案選項中文說明與詞性】\n(A) formally (正式地) (B) exactly (精確地) (C) formerly (以前) (D) hopefully (有希望地)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) formally\n解析說明：formally announced 表示「正式宣布」。4個選項為不同副詞單字，分類為「字彙」。"},
    {"id": "toetic_20260530_ans_113", "f": {"分類": "字彙"}, "ref": "toetic_20260530_ans 第113題", "q": "Just a decade ago even this type of slow processor was considered to be _______.", "o": ["(A) relative", "(B) decorative", "(C) informative", "(D) innovative"], "a": "D", "e": "【題目中文翻譯】\n就在十年前，即使是這種慢速處理器也被認為具有創新性。\n\n【答案選項中文說明與詞性】\n(A) relative (相對的) (B) decorative (裝飾性的) (C) informative (增進知識的) (D) innovative (創新的)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) innovative\n解析說明：considered to be innovative 表示「被認為是創新的」。4個選項為不同形容詞單字，分類為「字彙」。"},
    {"id": "toetic_20260530_ans_114", "f": {"分類": "詞性"}, "ref": "toetic_20260530_ans 第114題", "q": "With their reinforced outer layers, Beck's outdoor lamps can _______ well both the hot and cold weather.", "o": ["(A) withstands", "(B) withstood", "(C) withstand", "(D) withstanding"], "a": "C", "e": "【題目中文翻譯】\n憑藉其強化外層，貝克的戶外燈具能夠很好地抵禦酷暑和嚴寒。\n\n【答案選項中文說明與詞性】\n(A) withstands (動詞三單) (B) withstood (過去式) (C) withstand (動詞原形) (D) withstanding (分詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) withstand\n解析說明：助動詞 can 後面接原形動詞 withstand（承受/抵禦）。選項為同字根動詞時態與態樣變化，分類為「詞性」。"},
    {"id": "toetic_20260530_ans_115", "f": {"分類": "詞性"}, "ref": "toetic_20260530_ans 第115題", "q": "Victoria Community House will eventually be renovated _______ a library which will contain history_related books and videos.", "o": ["(A) inclusion", "(B) including", "(C) to include", "(D) included"], "a": "C", "e": "【題目中文翻譯】\n維多利亞社區中心最終將進行翻新，擴建一個包含歷史相關書籍和影片的圖書館。\n\n【答案選項中文說明與詞性】\n(A) inclusion (名詞) (B) including (介系詞/分詞) (C) to include (不定詞) (D) included (過去分詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) to include\n解析說明：to include... 作目的或結果不定詞片語「以包含.../翻新納入...」。選項為同字根衍生變化，分類為「詞性」。"},
    {"id": "toetic_20260530_ans_116", "f": {"分類": "字彙"}, "ref": "toetic_20260530_ans 第116題", "q": "The Sunshine Foundation provides _______ to local residents who lost their homes.", "o": ["(A) control", "(B) education", "(C) relief", "(D) representation"], "a": "C", "e": "【題目中文翻譯】\n陽光基金會向失去家園的當地居民提供救濟。\n\n【答案選項中文說明與詞性】\n(A) control (控制) (B) education (教育) (C) relief (救濟/援助) (D) representation (代表)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) relief\n解析說明：provide relief to... 表示「向...提供救濟/援助」。4個選項為不同名詞單字，分類為「字彙」。"},
    {"id": "toetic_20260530_ans_117", "f": {"分類": "介系詞"}, "ref": "toetic_20260530_ans 第117題", "q": "Ms. Harris needed to clear the round table _______ scattered documents after the product development meeting.", "o": ["(A) for", "(B) of", "(C) on", "(D) with"], "a": "B", "e": "【題目中文翻譯】\n產品開發會議結束後，哈里斯女士需要清空圓桌上散落的文件。\n\n【答案選項中文說明與詞性】\n(A) for (為了) (B) of (從...清掉) (C) on (在...上) (D) with (用)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(B) of\n解析說明：clear A of B 為固定片語，表示「清理A上的B（雜物/文件）」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "toetic_20260530_ans_118", "f": {"分類": "介系詞"}, "ref": "toetic_20260530_ans 第118題", "q": "Ms. Perry was evaluated very high _______ the fact that she brought in three large clients this quarter.", "o": ["(A) due to", "(B) even though", "(C) unless", "(D) whereas"], "a": "A", "e": "【題目中文翻譯】\n鑑於佩里女士本季度帶來了三位大客戶，她獲得了極高的評價。\n\n【答案選項中文說明與詞性】\n(A) due to (由於/鑑於, 介系詞) (B) even though (即使, 連接詞) (C) unless (除非, 連接詞) (D) whereas (然而, 連接詞)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(A) due to\n解析說明：後接名詞片語 the fact that...，應使用介系詞片語 due to。選項包含介系詞與連接詞，分類為「介系詞」。"},
    {"id": "toetic_20260530_ans_119", "f": {"分類": "字彙"}, "ref": "toetic_20260530_ans 第119題", "q": "One _______ of a good system project manager is the ability to coordinate people and other resources.", "o": ["(A) aspiration", "(B) attempt", "(C) position", "(D) characteristic"], "a": "D", "e": "【題目中文翻譯】\n一名優秀的系統專案經理的特徵之一是協調人員和其他資源的能力。\n\n【答案選項中文說明與詞性】\n(A) aspiration (抱負) (B) attempt (企圖) (C) position (職位) (D) characteristic (特徵/特質)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) characteristic\n解析說明：One characteristic of... 表示「...的特徵之一」。4個選項為不同名詞單字，分類為「字彙」。"},
    {"id": "toetic_20260530_ans_120", "f": {"分類": "字彙"}, "ref": "toetic_20260530_ans 第120題", "q": "The following notice is important and requires the _______ attention of the addressee.", "o": ["(A) consistent", "(B) immediate", "(C) late", "(D) optional"], "a": "B", "e": "【題目中文翻譯】\n以下通知非常重要，需要收件人立即關注。\n\n【答案選項中文說明與詞性】\n(A) consistent (一致的) (B) immediate (立即的) (C) late (遲到的) (D) optional (可選擇的)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) immediate\n解析說明：immediate attention 表示「立即的關注/即時處理」。4個選項為不同形容詞單字，分類為「字彙」。"},
    {"id": "toetic_20260530_ans_121", "f": {"分類": "字彙"}, "ref": "toetic_20260530_ans 第121題", "q": "_______ has been discussed about the mayor's resignation but there has been no official comment.", "o": ["(A) Another", "(B) Every", "(C) Much", "(D) Several"], "a": "C", "e": "【題目中文翻譯】\n關於市長辭職的事宜已經討論了很多，但尚未有官方回應。\n\n【答案選項中文說明與詞性】\n(A) Another (另一個) (B) Every (每個) (C) Much (許多/大量) (D) Several (好幾個)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) Much\n解析說明：Much 代替不可數討論量，作不可數主詞配合單數動詞 has been discussed。選項為不同代名詞/限定詞，分類為「字彙」。"},
    {"id": "toetic_20260530_ans_122", "f": {"分類": "字彙"}, "ref": "toetic_20260530_ans 第122題", "q": "Dr. Gerald Schmitz was proud to be one of _______ a few professors to receive the award in physics.", "o": ["(A) almost", "(B) among", "(C) those", "(D) only"], "a": "D", "e": "【題目中文翻譯】\n傑拉德·施密茨博士很自豪能成為僅有的幾位獲得物理學獎的教授之一。\n\n【答案選項中文說明與詞性】\n(A) almost (幾乎) (B) among (在...之中) (C) those (那些) (D) only (僅僅/唯一的)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) only\n解析說明：one of only a few... 表示「僅有的少數人之一」。4個選項為不同字彙，分類為「字彙」。"},
    {"id": "toetic_20260530_ans_123", "f": {"分類": "詞性"}, "ref": "toetic_20260530_ans 第123題", "q": "Please complete the _______ application form and return it to our company by November 21.", "o": ["(A) enclose", "(B) enclosed", "(C) enclosing", "(D) enclosure"], "a": "B", "e": "【題目中文翻譯】\n請填妥隨附的申請表，並於 11 月 21 日之前寄回本公司。\n\n【答案選項中文說明與詞性】\n(A) enclose (動詞原形) (B) enclosed (過去分詞/隨附的) (C) enclosing (現在分詞) (D) enclosure (名詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) enclosed\n解析說明：修飾名詞 application form，用過去分詞 enclosed 作形容詞「隨附的」。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "toetic_20260530_ans_124", "f": {"分類": "字彙"}, "ref": "toetic_20260530_ans 第124題", "q": "Tonghae Motors announced that it will be _______ its TM_2500 SUV because of a problem with the steering system.", "o": ["(A) advertising", "(B) developing", "(C) introducing", "(D) redesigning"], "a": "D", "e": "【題目中文翻譯】\n東海汽車宣布，由於轉向系統存在問題，將重新設計其 TM_2500 SUV。\n\n【答案選項中文說明與詞性】\n(A) advertising (廣告) (B) developing (開發) (C) introducing (介紹) (D) redesigning (重新設計)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) redesigning\n解析說明：語意因轉向系統有問題，故需要「重新設計 (redesigning)」。4個選項為不同動詞，分類為「字彙」。"},
    {"id": "toetic_20260530_ans_125", "f": {"分類": "連結詞"}, "ref": "toetic_20260530_ans 第125題", "q": "_______ she had excellent references, Ms. Baker's application for the position of executive assistant was accepted.", "o": ["(A) Although", "(B) As", "(C) Despite", "(D) Even if"], "a": "B", "e": "【題目中文翻譯】\n由於貝克女士擁有優秀的推薦信，她應徵執行助理職位的申請獲得了批准。\n\n【答案選項中文說明與詞性】\n(A) Although (雖然) (B) As (因為/由於) (C) Despite (儘管, 介系詞) (D) Even if (即使)\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(B) As\n解析說明：表示因果關係「因為/由於她有優秀推薦信」，用從屬連接詞 As。分類為「連結詞」。"},
    {"id": "toetic_20260530_ans_126", "f": {"分類": "連結詞"}, "ref": "toetic_20260530_ans 第126題", "q": "CircleMart sells two types of rechargeable batteries, both of _______ have been sold out for a few days.", "o": ["(A) that", "(B) what", "(C) which", "(D) whom"], "a": "C", "e": "【題目中文翻譯】\nCircleMart 銷售兩種充電電池，兩種電池都已經售罄好幾天了。\n\n【答案選項中文說明與詞性】\n(A) that (關係代名詞) (B) what (複合關代) (C) which (關係代名詞) (D) whom (人稱受格關代)\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(C) which\n解析說明：介系詞 of 後引導非限定關係子句修飾物 (batteries)，需使用關係代名詞 which (both of which)。分類為「連結詞」。"},
    {"id": "toetic_20260530_ans_127", "f": {"分類": "詞性"}, "ref": "toetic_20260530_ans 第127題", "q": "Micron Pharmaceuticals will postpone the launch of their new medication until its effect _______.", "o": ["(A) has been reconfirmed", "(B) reconfirm", "(C) reconfirmed", "(D) was reconfirmed"], "a": "A", "e": "【題目中文翻譯】\n美光製藥將推遲新藥的推出，直到其療效得到再次確認。\n\n【答案選項中文說明與詞性】\n(A) has been reconfirmed (現在完成被動式) (B) reconfirm (動詞原形) (C) reconfirmed (過去式) (D) was reconfirmed (過去被動式)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) has been reconfirmed\n解析說明：until 時間副詞子句中，用現在完成式代替未來完成式，且主詞 its effect 為被動關係，故選 has been reconfirmed。分類為「詞性」。"},
    {"id": "toetic_20260530_ans_128", "f": {"分類": "介系詞"}, "ref": "toetic_20260530_ans 第128題", "q": "Only the sturdy guardrail on the side of the road prevented the car _______ falling off the cliff.", "o": ["(A) from", "(B) of", "(C) through", "(D) with"], "a": "A", "e": "【題目中文翻譯】\n只有路邊堅固的護欄防止了汽車墜落山崖。\n\n【答案選項中文說明與詞性】\n(A) from (防止/來自) (B) of (的) (C) through (穿過) (D) with (和)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(A) from\n解析說明：prevent A from Ving 為固定搭配，表示「防止A做...」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "toetic_20260530_ans_129", "f": {"分類": "字彙"}, "ref": "toetic_20260530_ans 第129題", "q": "They are fighting against the _______ to retain their market share in the beverage industry.", "o": ["(A) chance", "(B) wind", "(C) wall", "(D) odds"], "a": "D", "e": "【題目中文翻譯】\n他們正在克服重重困難，以保持在飲料行業的市場份額。\n\n【答案選項中文說明與詞性】\n(A) chance (機會) (B) wind (風) (C) wall (牆) (D) odds (逆境/困難/機率)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) odds\n解析說明：fight against the odds 表示「克服重重困難/逆境搏鬥」。4個選項為不同名詞單字，分類為「字彙」。"},
    {"id": "toetic_20260530_ans_130", "f": {"分類": "字彙"}, "ref": "toetic_20260530_ans 第130題", "q": "Nothing is more important for a newspaper reporter than to find a _______ source of information.", "o": ["(A) changeable", "(B) dispensable", "(C) purchasable", "(D) reliable"], "a": "D", "e": "【題目中文翻譯】\n對於報社記者來說，沒有什麼比找到可靠的信息來源更重要的了。\n\n【答案選項中文說明與詞性】\n(A) changeable (易變的) (B) dispensable (可有可無的) (C) purchasable (可購買的) (D) reliable (可靠的)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) reliable\n解析說明：a reliable source of information 表示「可靠的資訊來源」。4個選項為不同形容詞單字，分類為「字彙」。"},
    {"id": "toeic_20260517_ans_101", "f": {"分類": "詞性"}, "ref": "toeic_20260517_ans 第101題", "q": "Since its launch, XJ400 has quickly become a _______ for the mobile phone industry.", "o": ["(A) standardize", "(B) standardizing", "(C) standardized", "(D) standard"], "a": "D", "e": "【題目中文翻譯】\n自推出以來，XJ400 已迅速成為手機行業的標準。\n\n【答案選項中文說明與詞性】\n(A) standardize (動詞) (B) standardizing (分詞) (C) standardized (分詞) (D) standard (名詞/標準)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) standard\n解析說明：冠詞 a 後面接名詞 standard 作補語。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "toeic_20260517_ans_102", "f": {"分類": "連結詞"}, "ref": "toeic_20260517_ans 第102題", "q": "Anyone interested in the Marketing Director position should immediately telephone Mr. Kim _______ visit him in person.", "o": ["(A) or", "(B) also", "(C) not", "(D) but"], "a": "A", "e": "【題目中文翻譯】\n任何對行銷總監職位感興趣的人應立即致電金先生或親自拜訪他。\n\n【答案選項中文說明與詞性】\n(A) or (或者, 對等連接詞) (B) also (也, 副詞) (C) not (不, 副詞) (D) but (但是, 連接詞)\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(A) or\n解析說明：telephone... or visit... 連接兩個平行動作（致電或親自拜訪），用對等連接詞 or。分類為「連結詞」。"},
    {"id": "toeic_20260517_ans_103", "f": {"分類": "詞性"}, "ref": "toeic_20260517_ans 第103題", "q": "After _______ the faulty parts of the printer, the repairperson gave it a thorough cleaning.", "o": ["(A) replace", "(B) replaced", "(C) replaces", "(D) replacing"], "a": "D", "e": "【題目中文翻譯】\n在更換印表機的故障零件後，維修人員對其進行了徹底的清潔。\n\n【答案選項中文說明與詞性】\n(A) replace (原形) (B) replaced (過去式) (C) replaces (三單) (D) replacing (動名詞/分詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) replacing\n解析說明：介系詞 After 後面接動名詞 replacing 作受詞。選項為同字根動詞變化，分類為「詞性」。"},
    {"id": "toeic_20260517_ans_104", "f": {"分類": "詞性"}, "ref": "toeic_20260517_ans 第104題", "q": "Those who live in this residential area should have good _______ to large shopping centers and supermarkets.", "o": ["(A) access", "(B) accessible", "(C) accessibly", "(D) accession"], "a": "A", "e": "【題目中文翻譯】\n居住在該住宅區的居民應能便利地前往大型購物中心和超市。\n\n【答案選項中文說明與詞性】\n(A) access (不可數名詞/進入/使用權) (B) accessible (形容詞) (C) accessibly (副詞) (D) accession (名詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) access\n解析說明：have good access to... 表示「可以方便使用/到達...」。形容詞 good 後接不可數名詞 access。分類為「詞性」。"},
    {"id": "toeic_20260517_ans_105", "f": {"分類": "詞性"}, "ref": "toeic_20260517_ans 第105題", "q": "Since the local companies scrapped unprofitable products and devoted more resources to products with more potential, _______ have started making profits.", "o": ["(A) their", "(B) theirs", "(C) them", "(D) they"], "a": "D", "e": "【題目中文翻譯】\n由於當地公司廢除了不盈利的產品，並將更多資源投入到更有潛力的產品中，他們已經開始獲利。\n\n【答案選項中文說明與詞性】\n(A) their (所有格) (B) theirs (所有格代名詞) (C) them (受格) (D) they (主格代名詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) they\n解析說明：主要子句需要主格代名詞 they 作動詞 have started 的主詞。屬代名詞格位變化，分類為「詞性」。"},
    {"id": "toeic_20260517_ans_106", "f": {"分類": "詞性"}, "ref": "toeic_20260517_ans 第106題", "q": "The _______ version of the keynote speech for next week's annual shareholders' meeting will be available later today.", "o": ["(A) final", "(B) finality", "(C) finalize", "(D) finally"], "a": "A", "e": "【題目中文翻譯】\n下週年度股東大會主題演講的最終版本將於今天晚些時候提供。\n\n【答案選項中文說明與詞性】\n(A) final (形容詞) (B) finality (名詞) (C) finalize (動詞) (D) finally (副詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) final\n解析說明：修飾名詞 version，需填入形容詞 final（最終的）。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "toeic_20260517_ans_107", "f": {"分類": "字彙"}, "ref": "toeic_20260517_ans 第107題", "q": "The division led by Mr. Davidson has recorded the best sales performance _______.", "o": ["(A) ever", "(B) never", "(C) since", "(D) until"], "a": "A", "e": "【題目中文翻譯】\n戴維森先生領導的部門創下了有史以來最好的銷售業績。\n\n【答案選項中文說明與詞性】\n(A) ever (有史以來/曾經) (B) never (從不) (C) since (自從) (D) until (直到)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) ever\n解析說明：the best... ever 表示「有史以來最好的...」。選項為不同副詞/介系詞，分類為「字彙」。"},
    {"id": "toeic_20260517_ans_108", "f": {"分類": "字彙"}, "ref": "toeic_20260517_ans 第108題", "q": "Mr. Henderson was recruited to head MNN Chemicals, Inc. in order to _______ the troubled firm.", "o": ["(A) recognize", "(B) recreate", "(C) reorganize", "(D) represent"], "a": "C", "e": "【題目中文翻譯】\n亨德森先生被招聘來領導 MNN 化工公司，以整頓這家陷入困境的公司。\n\n【答案選項中文說明與詞性】\n(A) recognize (認出) (B) recreate (重新創造) (C) reorganize (改組/整頓) (D) represent (代表)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) reorganize\n解析說明：in order to reorganize the troubled firm 表示「為了改組整頓這家困境中的公司」。4個選項為不同動詞，分類為「字彙」。"},
    {"id": "toeic_20260517_ans_109", "f": {"分類": "詞性"}, "ref": "toeic_20260517_ans 第109題", "q": "Mr. Anzai from CBC corporation _______ us a visit later this month.", "o": ["(A) paid", "(B) pays", "(C) will pay", "(D) has paid"], "a": "C", "e": "【題目中文翻譯】\nCBC 公司的安西先生將在本月晚些時候拜訪我們。\n\n【答案選項中文說明與詞性】\n(A) paid (過去式) (B) pays (三單) (C) will pay (未來式) (D) has paid (完成式)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) will pay\n解析說明：時間標示為 later this month（本月晚些時候），動詞應使用未來式 will pay。屬於時態變化，分類為「詞性」。"},
    {"id": "toeic_20260517_ans_110", "f": {"分類": "連結詞"}, "ref": "toeic_20260517_ans 第110題", "q": "Jim Thompson has decided to pursue a career in medicine _______ he still expresses a great interest in modern American arts.", "o": ["(A) since", "(B) so", "(C) although", "(D) unless"], "a": "C", "e": "【題目中文翻譯】\n儘管吉姆·湯普森仍對美國現代藝術表現出極大的興趣，但他已決定從事醫學事業。\n\n【答案選項中文說明與詞性】\n(A) since (因為/自從) (B) so (所以) (C) although (雖然/儘管) (D) unless (除非)\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(C) although\n解析說明：引導讓步狀語子句「雖然他仍對藝術有興趣」，用屬連接詞 although。分類為「連結詞」。"},
    {"id": "toeic_20260517_ans_111", "f": {"分類": "連結詞"}, "ref": "toeic_20260517_ans 第111題", "q": "Lida Ward was a dependable team player, _______ good judgment and mature outlook resulted in a logical and reliable approach to her endeavors.", "o": ["(A) what", "(B) which", "(C) whom", "(D) whose"], "a": "D", "e": "【題目中文翻譯】\n莉達·沃德是一位可靠的團隊成員，她的良好判斷力和成熟眼光使其工作方法邏輯嚴密且可靠。\n\n【答案選項中文說明與詞性】\n(A) what (複合關代) (B) which (關代) (C) whom (受格關代) (D) whose (所有格關代)\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(D) whose\n解析說明：先行詞為人 (Lida Ward)，修飾名詞片語 good judgment，需使用關係代名詞所有格 whose。分類為「連結詞」。"},
    {"id": "toeic_20260517_ans_112", "f": {"分類": "詞性"}, "ref": "toeic_20260517_ans 第112題", "q": "With their concerted efforts, the research team at Pacific Laboratories has finally gained _______ results in their new synthetic fabric development.", "o": ["(A) satisfaction", "(B) satisfy", "(C) satisfactory", "(D) satisfactorily"], "a": "C", "e": "【題目中文翻譯】\n經過共同努力，太平洋實驗室的研究團隊終於在新合成纖維開發方面取得了令人滿意的成果。\n\n【答案選項中文說明與詞性】\n(A) satisfaction (名詞) (B) satisfy (動詞) (C) satisfactory (形容詞) (D) satisfactorily (副詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) satisfactory\n解析說明：修飾名詞 results，需填入形容詞 satisfactory（令人滿意的）。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "toeic_20260517_ans_113", "f": {"分類": "字彙"}, "ref": "toeic_20260517_ans 第113題", "q": "To attract customers to your online business, experts say you should _______ update your Web site.", "o": ["(A) continually", "(B) increasingly", "(C) particularly", "(D) recently"], "a": "A", "e": "【題目中文翻譯】\n為了吸引客戶關注您的線上業務，專家表示您應該不斷更新您的網站。\n\n【答案選項中文說明與詞性】\n(A) continually (持續地/不斷地) (B) increasingly (漸增地) (C) particularly (特別地) (D) recently (最近地)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) continually\n解析說明：continually update... 表示「持續不斷地更新...」。4個選項為不同副詞單字，分類為「字彙」。"},
    {"id": "toeic_20260517_ans_114", "f": {"分類": "字彙"}, "ref": "toeic_20260517_ans 第114題", "q": "After working intensely on it for months, Jim Hant was finally able to _______ the deal with the telecom giant.", "o": ["(A) close", "(B) draw", "(C) form", "(D) open"], "a": "A", "e": "【題目中文翻譯】\n經過數月的密集努力，吉姆·漢特終於能夠與這家電信巨頭達成交易。\n\n【答案選項中文說明與詞性】\n(A) close (達成/敲定) (B) draw (繪製/拉) (C) form (形成) (D) open (開啟)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) close\n解析說明：close the deal 為固定搭配，表示「達成交易/敲定協議」。4個選項為不同動詞，分類為「字彙」。"},
    {"id": "toeic_20260517_ans_115", "f": {"分類": "字彙"}, "ref": "toeic_20260517_ans 第115題", "q": "More than 350 _______ restaurants in the bay area are listed on this food_related online directory.", "o": ["(A) proactive", "(B) probable", "(C) productive", "(D) promising"], "a": "D", "e": "【題目中文翻譯】\n該美食相關線上目錄中列出了灣區 350 多家有前途的餐廳。\n\n【答案選項中文說明與詞性】\n(A) proactive (積極主動的) (B) probable (可能的) (C) productive (富有成效的) (D) promising (有前途的/看好的)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) promising\n解析說明：promising restaurants 表示「有前途/發展潛力的餐廳」。4個選項為不同形容詞，分類為「字彙」。"},
    {"id": "toeic_20260517_ans_116", "f": {"分類": "詞性"}, "ref": "toeic_20260517_ans 第116題", "q": "The product development team _______ us the new product if it had been ready in time.", "o": ["(A) would be shown", "(B) would have been shown", "(C) would have shown", "(D) would show"], "a": "C", "e": "【題目中文翻譯】\n如果新產品及時準備好，產品開發團隊本來會向我們展示它的。\n\n【答案選項中文說明與詞性】\n(A) would be shown (被動) (B) would have been shown (完成被動) (C) would have shown (主動/與過去相反) (D) would show (原級主動)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) would have shown\n解析說明：假設法與過去事實相反：If + S + had p.p., S + would have p.p.。團隊主動向我們展示 (show us)，故選 would have shown。分類為「詞性」。"},
    {"id": "toeic_20260517_ans_117", "f": {"分類": "詞性"}, "ref": "toeic_20260517_ans 第117題", "q": "Marble University is considered the top academic _______ in the world for marine biology.", "o": ["(A) instituted", "(B) institutions", "(C) institutional", "(D) institution"], "a": "D", "e": "【題目中文翻譯】\n馬爾堡大學被認為是世界上海洋生物學領域頂尖的學術機構。\n\n【答案選項中文說明與詞性】\n(A) instituted (動詞過去式) (B) institutions (複數名詞) (C) institutional (形容詞) (D) institution (單數名詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) institution\n解析說明：the top academic institution（單數名詞），修飾大學主詞。選項為同字根詞性及單複數變化，分類為「詞性」。"},
    {"id": "toeic_20260517_ans_118", "f": {"分類": "介系詞"}, "ref": "toeic_20260517_ans 第118題", "q": "Mr. Emerson has assigned the sales promotion work _______ Joyce Morgan.", "o": ["(A) as", "(B) to", "(C) over", "(D) for"], "a": "B", "e": "【題目中文翻譯】\n愛默生先生已將促銷工作指派給喬伊斯·摩根。\n\n【答案選項中文說明與詞性】\n(A) as (作為) (B) to (給/向) (C) over (在...之上) (D) for (為了)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(B) to\n解析說明：assign A to B 表示「將A指派給B」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "toeic_20260517_ans_119", "f": {"分類": "字彙"}, "ref": "toeic_20260517_ans 第119題", "q": "Rebel Corporation is intent on becoming a major _______ in the world computer and communications market.", "o": ["(A) competition", "(B) force", "(C) lead", "(D) runner"], "a": "B", "e": "【題目中文翻譯】\nRebel 公司意圖成為世界電腦和通信市場的主要力量。\n\n【答案選項中文說明與詞性】\n(A) competition (競爭) (B) force (力量/勢力) (C) lead (領導) (D) runner (跑步者)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) force\n解析說明：a major force in the market 表示「市場上的主要力量/主要勢力」。4個選項為不同名詞單字，分類為「字彙」。"},
    {"id": "toeic_20260517_ans_120", "f": {"分類": "介系詞"}, "ref": "toeic_20260517_ans 第120題", "q": "Lower interest rates can positively affect corporate profits _______ decreased loan costs.", "o": ["(A) for", "(B) from", "(C) of", "(D) with"], "a": "D", "e": "【題目中文翻譯】\n較低的利率可以透過減少貸款成本對企業利潤產生積極影響。\n\n【答案選項中文說明與詞性】\n(A) for (為了) (B) from (來自) (C) of (的) (D) with (伴隨著/憑藉著)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(D) with\n解析說明：with decreased loan costs 介系詞片語表示「伴隨/透過減少的貸款成本」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "toeic_20260517_ans_121", "f": {"分類": "字彙"}, "ref": "toeic_20260517_ans 第121題", "q": "The Managing Director said that the company would have to take drastic _______ to address this situation.", "o": ["(A) fashions", "(B) measures", "(C) methods", "(D) ways"], "a": "B", "e": "【題目中文翻譯】\n總經理表示公司將不得不採取嚴厲措施來解決這種情況。\n\n【答案選項中文說明與詞性】\n(A) fashions (時尚) (B) measures (措施) (C) methods (方法) (D) ways (方式)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) measures\n解析說明：take drastic measures 為固定搭配，表示「採取嚴厲/果斷措施」。4個選項為不同名詞單字，分類為「字彙」。"},
    {"id": "toeic_20260517_ans_122", "f": {"分類": "字彙"}, "ref": "toeic_20260517_ans 第122題", "q": "A cooking contest took place between two of the city's most _______ chefs.", "o": ["(A) compassionate", "(B) sincere", "(C) prominent", "(D) wealthy"], "a": "C", "e": "【題目中文翻譯】\n該市兩位最傑出的廚師之間舉行了一場烹飪比賽。\n\n【答案選項中文說明與詞性】\n(A) compassionate (有同情心的) (B) sincere (真誠的) (C) prominent (傑出的/著名的) (D) wealthy (富有的)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) prominent\n解析說明：prominent chefs 表示「傑出/著名的廚師」。4個選項為不同形容詞單字，分類為「字彙」。"},
    {"id": "toeic_20260517_ans_123", "f": {"分類": "介系詞"}, "ref": "toeic_20260517_ans 第123題", "q": "According to the manufacturer, NP_445B is equivalent _______ NT_38 that is out of production.", "o": ["(A) after", "(B) to", "(C) in", "(D) at"], "a": "B", "e": "【題目中文翻譯】\n據製造商稱，NP_445B 等同於已停產的 NT_38。\n\n【答案選項中文說明與詞性】\n(A) after (在...之後) (B) to (對/等同於) (C) in (在...裡面) (D) at (在)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(B) to\n解析說明：be equivalent to... 為固定搭配，表示「等同於...」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "toeic_20260517_ans_124", "f": {"分類": "字彙"}, "ref": "toeic_20260517_ans 第124題", "q": "This facility has conducted emergency _______ involving local police several times.", "o": ["(A) alarms", "(B) bills", "(C) drills", "(D) kits"], "a": "C", "e": "【題目中文翻譯】\n該設施已多次組織當地警察進行緊急演習。\n\n【答案選項中文說明與詞性】\n(A) alarms (警報) (B) bills (帳單) (C) drills (演習/訓練) (D) kits (工具包)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) drills\n解析說明：conduct emergency drills 表示「進行緊急演習」。4個選項為不同名詞單字，分類為「字彙」。"},
    {"id": "toeic_20260517_ans_125", "f": {"分類": "字彙"}, "ref": "toeic_20260517_ans 第125題", "q": "Both the city mayor and the city council promised that they would immediately _______ funds for the popular project.", "o": ["(A) adequate", "(B) appropriate", "(C) proper", "(D) relevant"], "a": "B", "e": "【題目中文翻譯】\n市長和市議會都承諾，他們將立即為這個受歡迎的項目撥款。\n\n【答案選項中文說明與詞性】\n(A) adequate (足夠的) (B) appropriate (動詞:撥款/挪用) (C) proper (適當的) (D) relevant (相關的)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) appropriate\n解析說明：appropriate funds 在此作動詞，表示「撥出款項/劃撥資金」。4個選項字義不同，分類為「字彙」。"},
    {"id": "toeic_20260517_ans_126", "f": {"分類": "字彙"}, "ref": "toeic_20260517_ans 第126題", "q": "Starting next month, routine fire safety inspections will be _______ on a monthly basis.", "o": ["(A) alerted", "(B) conducted", "(C) engaged", "(D) protected"], "a": "B", "e": "【題目中文翻譯】\n從下個月開始，將每月進行定期消防安全檢查。\n\n【答案選項中文說明與詞性】\n(A) alerted (警惕) (B) conducted (執行/進行) (C) engaged (參與) (D) protected (保護)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) conducted\n解析說明：inspections will be conducted 表示「檢查將被執行/進行」。4個選項為不同動詞，分類為「字彙」。"},
    {"id": "toeic_20260517_ans_127", "f": {"分類": "字彙"}, "ref": "toeic_20260517_ans 第127題", "q": "If the paperwork arrives on time, _______ in the accounting division should process this payment by Friday.", "o": ["(A) whatever", "(B) someone", "(C) which", "(D) who"], "a": "B", "e": "【題目中文翻譯】\n如果文件按時到達，會計部門的人應該在星期五之前處理這筆付款。\n\n【答案選項中文說明與詞性】\n(A) whatever (無論什麼) (B) someone (某人) (C) which (哪一個) (D) who (誰)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) someone\n解析說明：someone in the accounting division 表示「會計部門的某個人」。選項為不同不定代名詞，分類為「字彙」。"},
    {"id": "toeic_20260517_ans_128", "f": {"分類": "字彙"}, "ref": "toeic_20260517_ans 第128題", "q": "Customer service representatives are specially trained in _______ with dissatisfied customers.", "o": ["(A) dealing", "(B) following", "(C) managing", "(D) persuading"], "a": "A", "e": "【題目中文翻譯】\n客戶服務代表接受過應對不滿意客戶的專門培訓。\n\n【答案選項中文說明與詞性】\n(A) dealing (處理/應對) (B) following (跟隨) (C) managing (管理) (D) persuading (說服)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) dealing\n解析說明：deal with... 表示「處理/應對...」。4個選項為不同動詞，分類為「字彙」。"},
    {"id": "toeic_20260517_ans_129", "f": {"分類": "詞性"}, "ref": "toeic_20260517_ans 第129題", "q": "The investment firm has agreed _______ 100 million dollars for this amusement complex project.", "o": ["(A) being paid", "(B) paying", "(C) to pay", "(D) pay"], "a": "C", "e": "【題目中文翻譯】\n該投資公司已同意為該娛樂綜合體項目支付 1 億美元。\n\n【答案選項中文說明與詞性】\n(A) being paid (被動) (B) paying (動名詞) (C) to pay (不定詞) (D) pay (原形)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) to pay\n解析說明：agree 後面接不定詞 to V (agree to pay)。屬動詞句型與詞性結構變化，分類為「詞性」。"},
    {"id": "toeic_20260517_ans_130", "f": {"分類": "字彙"}, "ref": "toeic_20260517_ans 第130題", "q": "Ms. Moody was told she would be transferred to an _______ company sometime in the first quarter next year.", "o": ["(A) associable", "(B) artificial", "(C) affiliated", "(D) automatic"], "a": "C", "e": "【題目中文翻譯】\n穆迪女士被告知她將於明年第一季度的某個時候被調往一家關係企業/子公司。\n\n【答案選項中文說明與詞性】\n(A) associable (可聯想的) (B) artificial (人造的) (C) affiliated (附屬的/關係企業的) (D) automatic (自動的)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) affiliated\n解析說明：an affiliated company 表示「關係企業/子公司」。4個選項為不同形容詞單字，分類為「字彙」。"},
    {"id": "toeic20060405_ans_101", "f": {"分類": "詞性"}, "ref": "toeic20060405_ans 第101題", "q": "The information session will provide an overview of the basic legal _______ that small businesses have been facing in the competitive market.", "o": ["(A) issuable", "(B) issued", "(C) issues", "(D) issuing"], "a": "C", "e": "【題目中文翻譯】\n簡報會將概述小企業在競爭市場中面臨的基本法律問題。\n\n【答案選項中文說明與詞性】\n(A) issuable (形容詞) (B) issued (過去分詞) (C) issues (複數名詞) (D) issuing (現在分詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) issues\n解析說明：修飾語形容詞 legal 後面接名詞 issues 作賓語。選項為同字根衍生詞變化，分類為「詞性」。"},
    {"id": "toeic20060405_ans_102", "f": {"分類": "詞性"}, "ref": "toeic20060405_ans 第102題", "q": "The security guards _______ supposed to meet at 7:15 A.M. in front of the main gate of the event site.", "o": ["(A) are", "(B) has", "(C) have", "(D) is"], "a": "A", "e": "【題目中文翻譯】\n保安人員應於上午 7:15 在活動現場主門前集合。\n\n【答案選項中文說明與詞性】\n(A) are (複數) (B) has (單數) (C) have (有) (D) is (單數)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) are\n解析說明：主詞 The security guards 為複數名詞，be supposed to 結構中 be 動詞應用 are。屬於動詞一致性變化，分類為「詞性」。"},
    {"id": "toeic20060405_ans_103", "f": {"分類": "詞性"}, "ref": "toeic20060405_ans 第103題", "q": "Mr. Roberts finished _______ the newspaper article on global warming just before the deadline.", "o": ["(A) edit", "(B) editing", "(C) to edit", "(D) to editing"], "a": "B", "e": "【題目中文翻譯】\n羅伯茨先生在截止日期前剛剛完成了關於全球變暖的報紙文章的編輯。\n\n【答案選項中文說明與詞性】\n(A) edit (原形) (B) editing (動名詞) (C) to edit (不定詞) (D) to editing (錯誤結構)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) editing\n解析說明：finish 後接動名詞 Ving (finish editing)。屬於動詞句型變化，分類為「詞性」。"},
    {"id": "toeic20060405_ans_104", "f": {"分類": "連結詞"}, "ref": "toeic20060405_ans 第104題", "q": "In case there is any change in _______ your address or phone number, please inform us as soon as possible.", "o": ["(A) either", "(B) both", "(C) neither", "(D) but also"], "a": "A", "e": "【題目中文翻譯】\n如果您的地址或電話號碼有任何變更，請儘快通知我們。\n\n【答案選項中文說明與詞性】\n(A) either (兩者之一) (B) both (兩者都) (C) neither (兩者都不) (D) but also (而且)\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(A) either\n解析說明：either A or B（A或B兩者之一）對等連接詞搭配。分類為「連結詞」。"},
    {"id": "toeic20060405_ans_105", "f": {"分類": "詞性"}, "ref": "toeic20060405_ans 第105題", "q": "Many critics praised the _______ performances in the movie, and it became a major hit.", "o": ["(A) impressed", "(B) impression", "(C) impressionable", "(D) impressive"], "a": "D", "e": "【題目中文翻譯】\n許多影評人讚揚了電影中令人印象深刻的表演，這部電影成為一部大熱之作。\n\n【答案選項中文說明與詞性】\n(A) impressed (感到的) (B) impression (名詞) (C) impressionable (易受影響的) (D) impressive (令人印象深刻的)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) impressive\n解析說明：修飾名詞 performances，應使用形容詞 impressive（令人印深刻的）。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "toeic20060405_ans_106", "f": {"分類": "詞性"}, "ref": "toeic20060405_ans 第106題", "q": "After the civil engineering firm submitted the necessary documents, City Hall let _______ go ahead with the bridgework.", "o": ["(A) their", "(B) theirs", "(C) them", "(D) they"], "a": "C", "e": "【題目中文翻譯】\n在土木工程公司提交必要的文件後，市政廳允許他們繼續進行橋樑工程。\n\n【答案選項中文說明與詞性】\n(A) their (所有格) (B) theirs (所有格代名詞) (C) them (受格) (D) they (主格)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) them\n解析說明：使役動詞 let 後接受格代名詞 them 作受詞 (let them go)。屬代名詞格位變化，分類為「詞性」。"},
    {"id": "toeic20060405_ans_107", "f": {"分類": "介系詞"}, "ref": "toeic20060405_ans 第107題", "q": "_______ to employment at Blackstone Financial, Inc., Ms. Nakayama served as a support staff member at Martin International Co.", "o": ["(A) Ahead", "(B) Before", "(C) Earlier", "(D) Prior"], "a": "D", "e": "【題目中文翻譯】\n在入職黑石金融公司之前，中山女士在馬丁國際公司擔任支援人員。\n\n【答案選項中文說明與詞性】\n(A) Ahead (在...前面) (B) Before (在...之前) (C) Earlier (更早) (D) Prior (在...之前)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(D) Prior\n解析說明：prior to + N 表示「在...之前」，作介系詞片語使用。分類為「介系詞」。"},
    {"id": "toeic20060405_ans_108", "f": {"分類": "詞性"}, "ref": "toeic20060405_ans 第108題", "q": "Of all the beverages in the taste test, Citrus Squeeze was chosen as the _______.", "o": ["(A) more refreshing", "(B) most refreshing", "(C) refresh", "(D) refreshing"], "a": "B", "e": "【題目中文翻譯】\n在品嘗測試的所有飲料中，Citrus Squeeze 被選為最令人心曠神怡的飲料。\n\n【答案選項中文說明與詞性】\n(A) more refreshing (比較級) (B) most refreshing (最高級) (C) refresh (動詞) (D) refreshing (原級形容詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) most refreshing\n解析說明：Of all the beverages（在所有飲料中）限定三者以上的範圍，用最高級 the most refreshing。分類為「詞性」。"},
    {"id": "toeic20060405_ans_109", "f": {"分類": "詞性"}, "ref": "toeic20060405_ans 第109題", "q": "They said their time was spent _______ at the lecture gaining a new perspective on the field of logistics.", "o": ["(A) productive", "(B) productively", "(C) productiveness", "(D) productivity"], "a": "B", "e": "【題目中文翻譯】\n他們說他們在講座上充實地度過了時間，獲得了物流領域的新視角。\n\n【答案選項中文說明與詞性】\n(A) productive (形容詞) (B) productively (副詞) (C) productiveness (名詞) (D) productivity (名詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) productively\n解析說明：spend time productively 用副詞修飾動詞被動結構 was spent。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "toeic20060405_ans_110", "f": {"分類": "介系詞"}, "ref": "toeic20060405_ans 第110題", "q": "Their new laptop is much more lightweight and inexpensive compared _______ their previous model.", "o": ["(A) for", "(B) in", "(C) of", "(D) to"], "a": "D", "e": "【題目中文翻譯】\n與之前的機型相比，他們的新款筆記本電腦更輕巧、更便宜。\n\n【答案選項中文說明與詞性】\n(A) for (為了) (B) in (在...裡面) (C) of (的) (D) to (與...相比)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(D) to\n解析說明：compared to... / compared with... 為固定介系詞片語「與...相比」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "toeic20060405_ans_111", "f": {"分類": "連結詞"}, "ref": "toeic20060405_ans 第111題", "q": "A complimentary copy of our informative booklet, Smart Investment Guide, is available for all those _______ attend the seminar.", "o": ["(A) what", "(B) where", "(C) which", "(D) who"], "a": "D", "e": "【題目中文翻譯】\n所有參加研討會的人都可以免費獲得我們內容豐富的小冊子《明智投資指南》。\n\n【答案選項中文說明與詞性】\n(A) what (複合關代) (B) where (關係副詞) (C) which (物) (D) who (人)\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(D) who\n解析說明：those who attend...（那些參加...的人），先行詞 those 指人，引導關係子句需用關係代名詞 who。分類為「連結詞」。"},
    {"id": "toeic20060405_ans_112", "f": {"分類": "詞性"}, "ref": "toeic20060405_ans 第112題", "q": "Mr. Kim used his _______ in the finance industry to help his acquaintance obtain a job after graduating from college.", "o": ["(A) connecting", "(B) connections", "(C) connector", "(D) connects"], "a": "B", "e": "【題目中文翻譯】\n金先生利用他在金融界的關係，幫助他的熟人在大學畢業後找到了一份工作。\n\n【答案選項中文說明與詞性】\n(A) connecting (分詞) (B) connections (名詞/人脈關係) (C) connector (名詞/連接器) (D) connects (動詞三單)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) connections\n解析說明：所有格 his 後面接名詞 connections（人脈關係）。選項為同字根衍生變化，分類為「詞性」。"},
    {"id": "toeic20060405_ans_113", "f": {"分類": "字彙"}, "ref": "toeic20060405_ans 第113題", "q": "Recently, demand for domestic products has been increasing, _______ in the automotive sector.", "o": ["(A) especially", "(B) habitually", "(C) hardly", "(D) scarcely"], "a": "A", "e": "【題目中文翻譯】\n最近對國產產品的需求一直在增加，尤其是在汽車領域。\n\n【答案選項中文說明與詞性】\n(A) especially (特別是/尤其) (B) habitually (習慣性地) (C) hardly (幾乎不) (D) scarcely (幾乎不)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) especially\n解析說明：especially in... 表示「特別是在...領域」。4個選項為不同副詞單字，分類為「字彙」。"},
    {"id": "toeic20060405_ans_114", "f": {"分類": "連結詞"}, "ref": "toeic20060405_ans 第114題", "q": "Some professional chefs recommend serrated kitchen knives because _______ they do not slice as smoothly as fine_edged ones, they never need sharpening.", "o": ["(A) instead", "(B) neither", "(C) still", "(D) while"], "a": "D", "e": "【題目中文翻譯】\n一些專業廚師推薦鋸齒廚刀，因為雖然它們切起來不如細刃廚刀平滑，但它們永遠不需要磨刀。\n\n【答案選項中文說明與詞性】\n(A) instead (相反地) (B) neither (兩者都不) (C) still (仍然) (D) while (雖然/儘管)\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(D) while\n解析說明：引導讓步對比子句「雖然...但是...」，需使用屬從屬連接詞 while。分類為「連結詞」。"},
    {"id": "toeic20060405_ans_115", "f": {"分類": "詞性"}, "ref": "toeic20060405_ans 第115題", "q": "By the end of next month, Mr. Harrison's team will _______ this long_term marketing project.", "o": ["(A) be finished", "(B) finishing", "(C) have finished", "(D) have been finished"], "a": "C", "e": "【題目中文翻譯】\n到下個月底，哈里森先生的團隊將完成這個長期行銷項目。\n\n【答案選項中文說明與詞性】\n(A) be finished (被動) (B) finishing (分詞) (C) have finished (未來完成主動) (D) have been finished (未來完成被動)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) have finished\n解析說明：By the end of next month 為未來完成式時間標記 (will have p.p.)，且團隊主動完成專案，故選 have finished。分類為「詞性」。"},
    {"id": "toeic20060405_ans_116", "f": {"分類": "字彙"}, "ref": "toeic20060405_ans 第116題", "q": "Environmental activists have long advocated the use of more _______ energy sources such as solar and wind power.", "o": ["(A) diverse", "(B) monotonous", "(C) standardized", "(D) unified"], "a": "A", "e": "【題目中文翻譯】\n環保人士長期以來一直倡導使用更多多元化的能源，例如太陽能和風能。\n\n【答案選項中文說明與詞性】\n(A) diverse (多元化的) (B) monotonous (單調的) (C) standardized (標準化的) (D) unified (統一的)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) diverse\n解析說明：diverse energy sources 表示「多元化/多樣化的能源」。4個選項為不同形容詞單字，分類為「字彙」。"},
    {"id": "toeic20060405_ans_117", "f": {"分類": "介系詞"}, "ref": "toeic20060405_ans 第117題", "q": "People attributed the company's improved business results _______ the decisiveness of the former CEO.", "o": ["(A) from", "(B) in", "(C) on", "(D) to"], "a": "D", "e": "【題目中文翻譯】\n人們將公司業績的改善歸功於前執行長的的果斷。\n\n【答案選項中文說明與詞性】\n(A) from (來自) (B) in (在) (C) on (在...上) (D) to (歸因於)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(D) to\n解析說明：attribute A to B 為固定搭配，表示「將A歸因於/歸功於B」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "toeic20060405_ans_118", "f": {"分類": "介系詞"}, "ref": "toeic20060405_ans 第118題", "q": "Ms. Perry was evaluated very high _______ the fact that she brought in three large clients this quarter.", "o": ["(A) due to", "(B) even though", "(C) unless", "(D) whereas"], "a": "A", "e": "【題目中文翻譯】\n鑑於佩里女士本季度帶來了三位大客戶，她獲得了極高的評價。\n\n【答案選項中文說明與詞性】\n(A) due to (由於, 介系詞) (B) even though (即使) (C) unless (除非) (D) whereas (然而)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(A) due to\n解析說明：due to the fact that... 表示「由於/鑑於...的事實」。選項包含介系詞與連接詞，分類為「介系詞」。"},
    {"id": "toeic20060405_ans_119", "f": {"分類": "字彙"}, "ref": "toeic20060405_ans 第119題", "q": "The CEO mentioned that the employee's longtime effort finally _______ off as their yearly sales doubled.", "o": ["(A) cut", "(B) paid", "(C) put", "(D) set"], "a": "B", "e": "【題目中文翻譯】\n執行長提到，隨著年度銷售額翻倍，員工長期以來的努力終於得到了回報。\n\n【答案選項中文說明與詞性】\n(A) cut (切) (B) paid (付出/回報) (C) put (放置) (D) set (設置)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) paid\n解析說明：pay off 為固定動詞片語，表示「得到回報/取得成功」。4個選項為不同動詞，分類為「字彙」。"},
    {"id": "toeic20060405_ans_120", "f": {"分類": "詞性"}, "ref": "toeic20060405_ans 第120題", "q": "As she thought about her job prospects in the current economy, Ms. Connor became _______ optimistic.", "o": ["(A) increase", "(B) increased", "(C) increasing", "(D) increasingly"], "a": "D", "e": "【題目中文翻譯】\n當她思考當前經濟形勢下的求職前景時，康納女士變得越來越樂觀。\n\n【答案選項中文說明與詞性】\n(A) increase (動詞/名詞) (B) increased (分詞) (C) increasing (分詞) (D) increasingly (副詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) increasingly\n解析說明：修飾形容詞 optimistic，應填入副詞 increasingly（越來越/日趨地）。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "toeic20060405_ans_121", "f": {"分類": "字彙"}, "ref": "toeic20060405_ans 第121題", "q": "We are writing to _______ about the schedule delay for the underground mall repair work.", "o": ["(A) acquire", "(B) conquer", "(C) inquire", "(D) require"], "a": "C", "e": "【題目中文翻譯】\n我們致函旨在詢問地下商場維修工程進度延誤的情況。\n\n【答案選項中文說明與詞性】\n(A) acquire (取得) (B) conquer (征服) (C) inquire (詢問) (D) require (要求)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) inquire\n解析說明：inquire about... 表示「詢問/打聽...」。4個選項為拼寫相似但意義不同的生字，分類為「字彙」。"},
    {"id": "toeic20060405_ans_122", "f": {"分類": "字彙"}, "ref": "toeic20060405_ans 第122題", "q": "Everyone at the meeting was impressed with Mr. Lee's _______ plan for the coming trade show.", "o": ["(A) collaborate", "(B) elaborate", "(C) evaporate", "(D) incorporate"], "a": "B", "e": "【題目中文翻譯】\n會議上的每個人都對李先生為即將到來的貿易展覽會所做的周密計劃印象深刻。\n\n【答案選項中文說明與詞性】\n(A) collaborate (合作) (B) elaborate (精心的/周密的) (C) evaporate (蒸發) (D) incorporate (包含)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) elaborate\n解析說明：elaborate plan 表示「精心的/周密的計劃」。4個選項為不同字彙，分類為「字彙」。"},
    {"id": "toeic20060405_ans_123", "f": {"分類": "介系詞"}, "ref": "toeic20060405_ans 第123題", "q": "All the participants _______ this year's architecture competition submitted truly outstanding and innovative designs.", "o": ["(A) on", "(B) from", "(C) in", "(D) by"], "a": "C", "e": "【題目中文翻譯】\n今年建築競賽的所有參賽者都提交了非常優秀且富有創意的設計。\n\n【答案選項中文說明與詞性】\n(A) on (在) (B) from (來自) (C) in (在...之中/參與) (D) by (由)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(C) in\n解析說明：participants in the competition 表示「競賽的參賽者/參與者」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "toeic20060405_ans_124", "f": {"分類": "詞性"}, "ref": "toeic20060405_ans 第124題", "q": "There will be a temporary _______ of gas service next Friday, November 12 between noon and 4:00 P.M.", "o": ["(A) suspend", "(B) suspended", "(C) suspension", "(D) suspending"], "a": "C", "e": "【題目中文翻譯】\n下週五（11 月 12 日）中午 12:00 至下午 4:00 期間，天然氣服務將暫時中斷。\n\n【答案選項中文說明與詞性】\n(A) suspend (動詞) (B) suspended (過去式) (C) suspension (名詞) (D) suspending (分詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) suspension\n解析說明：冠詞 a 與形容詞 temporary 後面接名詞 suspension（中斷/暫停）。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "toeic20060405_ans_125", "f": {"分類": "字彙"}, "ref": "toeic20060405_ans 第125題", "q": "The assembly line in the Hartford plant has been _______ automated over the past two decades.", "o": ["(A) finely", "(B) formerly", "(C) fully", "(D) frequently"], "a": "C", "e": "【題目中文翻譯】\n哈特福德工廠的裝配線在過去二十年中已實現完全自動化。\n\n【答案選項中文說明與詞性】\n(A) finely (精細地) (B) formerly (以前) (C) fully (完全地/充分地) (D) frequently (頻繁地)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) fully\n解析說明：fully automated 表示「完全自動化的」。4個選項為不同副詞單字，分類為「字彙」。"},
    {"id": "toeic20060405_ans_126", "f": {"分類": "連結詞"}, "ref": "toeic20060405_ans 第126題", "q": "_______ sales of the new product have picked up, the quarterly forecast will be met.", "o": ["(A) Because of", "(B) In case of", "(C) Now that", "(D) Unless"], "a": "C", "e": "【題目中文翻譯】\n既然新產品的銷售額有所好轉，季度預測目標將會實現。\n\n【答案選項中文說明與詞性】\n(A) Because of (由於, 介系詞) (B) In case of (萬一, 介系詞) (C) Now that (既然/由於, 連接詞) (D) Unless (除非, 連接詞)\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(C) Now that\n解析說明：引導原因副詞子句（因為/既然...），且後接完整句子，應選屬連接詞的 Now that。分類為「連結詞」。"},
    {"id": "toeic20060405_ans_127", "f": {"分類": "字彙"}, "ref": "toeic20060405_ans 第127題", "q": "As he was a _______ technician, Mark Smith could easily figure out the problem with the network.", "o": ["(A) comprehensive", "(B) competent", "(C) formal", "(D) supplemental"], "a": "B", "e": "【題目中文翻譯】\n由於馬克·史密斯是一位勝任的技術人員，他可以輕鬆找出網路問題。\n\n【答案選項中文說明與詞性】\n(A) comprehensive (全面的) (B) competent (勝任的/有能力的) (C) formal (正式的) (D) supplemental (補充的)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) competent\n解析說明：a competent technician 表示「一名勝任的/技術過硬的技術人員」。4個選項為不同形容詞單字，分類為「字彙」。"},
    {"id": "toeic20060405_ans_128", "f": {"分類": "介系詞"}, "ref": "toeic20060405_ans 第128題", "q": "Emercy Corporation received many thanks from some local charities who will divide the donated clothes _______ themselves.", "o": ["(A) among", "(B) inside", "(C) through", "(D) without"], "a": "A", "e": "【題目中文翻譯】\n埃默西公司收到了當地一些慈善機構的許多感謝，這些機構將在他們之間分配捐贈的衣服。\n\n【答案選項中文說明與詞性】\n(A) among (在...之間/三者以上) (B) inside (在...內部) (C) through (透過) (D) without (沒有)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(A) among\n解析說明：divide... among themselves 表示「在他們（多個慈善機構）之間分配...」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "toeic20060405_ans_129", "f": {"分類": "詞性"}, "ref": "toeic20060405_ans 第129題", "q": "Our insurance underwriter has decided to cancel our policy so we will have to select an _______ insurance carrier.", "o": ["(A) alternated", "(B) alternating", "(C) alternative", "(D) alternator"], "a": "C", "e": "【題目中文翻譯】\n我們的保險承保人決定取消我們的保單，因此我們將不得不選擇另一家替代的保險公司。\n\n【答案選項中文說明與詞性】\n(A) alternated (分詞) (B) alternating (分詞) (C) alternative (形容詞:替代的) (D) alternator (名詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) alternative\n解析說明：修飾名詞片語 insurance carrier，需填入形容詞 alternative（替代的）。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "toeic20060405_ans_130", "f": {"分類": "字彙"}, "ref": "toeic20060405_ans 第130題", "q": "The software designers thought their instructions were _______ enough, and they received almost no questions from users.", "o": ["(A) decreased", "(B) depressed", "(C) determined", "(D) detailed"], "a": "D", "e": "【題目中文翻譯】\n軟體設計師認為他們的說明足夠詳細，幾乎沒有收到使用者的疑問。\n\n【答案選項中文說明與詞性】\n(A) decreased (減少的) (B) depressed (沮喪的) (C) determined (堅定的) (D) detailed (詳細的)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) detailed\n解析說明：detailed enough 表示「足夠詳細」。4個選項為不同形容詞單字，分類為「字彙」。"},
  ]
});
